contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: takes a deposit amount and drives deposit() then withdrawAll()
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        // record balances before any interaction
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // perform a deposit into c (may be zero)
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // record balances after deposit and before withdraw
        uint afterDepositC = address(c).balance;
        uint afterDepositThis = address(this).balance;

        // call withdrawAll and capture whether it reverted
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // record balances after withdrawAll
        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;

        // General invariant: the combined observable Ether (address(c).balance + address(this).balance)
        // after withdrawAll must be <= the combined observable Ether immediately after deposit.
        // This ensures withdrawAll cannot create Ether out of thin air for these observable accounts.
        assert(afterC + afterThis <= afterDepositC + afterDepositThis);
    }

    receive() external payable {}
}

